839	// statusJSON is the JSON output for `entire status --json`.
840	type statusJSON struct {
841		Enabled        bool               `json:"enabled"`
842		Agents         []string           `json:"agents"`
843		ActiveSessions []sessionBriefJSON `json:"active_sessions"`
844		// AgentHelp is the machine-readable pointer for no-channel agents that parse
845		// `entire status --json` instead of the human footer. Set only on the
846		// success path (mirrors writeAgentHelpHint, which only renders when set up).
847		AgentHelp string `json:"agent_help,omitempty"`
848		// HooksOutdated lists agents whose installed hook config is out of date and
849		// should be refreshed with `entire enable --force`.
850		HooksOutdated []string `json:"hooks_outdated,omitempty"`
851		// CodexHooks reports effective discovery/trust warnings separately from
852		// current-checkout installation and freshness semantics.
853		CodexHooks *codexHooksStatusJSON `json:"codex_hooks,omitempty"`
854		// CheckpointSyncRemote is the elected checkpoint sync remote name, or the
855		// org/repo slug in dedicated checkpoint_remote mode. Deliberately not named
856		// checkpoint_remote, which is the existing GitHub-coupled setting.
857		CheckpointSyncRemote       string `json:"checkpoint_sync_remote,omitempty"`
858		CheckpointSyncRemoteSource string `json:"checkpoint_sync_remote_source,omitempty"` // config|observed|default|sole|first|dedicated
859		CheckpointSyncError        string `json:"checkpoint_sync_error,omitempty"`         // fail-closed message
860		UnpushedCheckpoints        int    `json:"unpushed_checkpoints,omitempty"`
861		// CheckpointRemoteIgnored/-Reason report a configured checkpoint_remote the
862		// ownership check rejected as inherited with the clone (reads and pushes
863		// fall back to the elected remote). Mirrors the text path's warning line.
864		CheckpointRemoteIgnored       string `json:"checkpoint_remote_ignored,omitempty"`
865		CheckpointRemoteIgnoredReason string `json:"checkpoint_remote_ignored_reason,omitempty"`
866		// SecretScanners lists the enabled engines when non-default; omitted when default.
867		SecretScanners []string `json:"secret_scanners,omitempty"`
868		Error          string   `json:"error,omitempty"`
869	}
