128	// GetRemoteURL returns the URL configured for the named git remote.
129	func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
130		return GetRemoteURLInDir(ctx, "", remoteName)
131	}
132	
133	// GetRemoteURLInDir returns the URL configured for the named git remote in dir.
134	func GetRemoteURLInDir(ctx context.Context, dir, remoteName string) (string, error) {
135		cmd := exec.CommandContext(ctx, "git", "remote", "get-url", remoteName)
136		if dir != "" {
137			cmd.Dir = dir
138		}
139		output, err := cmd.Output()
140		if err != nil {
141			return "", fmt.Errorf("remote %q not found", remoteName)
142		}
143		return strings.TrimSpace(string(output)), nil
144	}
145	
146	// GetPushURLs returns every URL a push to remoteName delivers to, in the order
147	// git will use them.
148	//
149	// A remote's push destinations are remote.<name>.pushurl when any is set and its
150	// remote.<name>.url otherwise (git's push_url_of_remote), and BOTH may repeat —
151	// git pushes to all of them, in config order. So this, not GetRemoteURL,
152	// describes where a push actually goes; GetRemoteURL reports the FETCH URL,
153	// which can name a different repository entirely.
154	//
155	// Returns at least one entry on success.
156	func GetPushURLs(ctx context.Context, remoteName string) ([]string, error) {
157		cmd := exec.CommandContext(ctx, "git", "remote", "get-url", "--push", "--all", remoteName)
158		output, err := cmd.Output()
159		if err != nil {
160			return nil, fmt.Errorf("remote %q not found", remoteName)
161		}
162		var urls []string
163		for _, line := range strings.Split(string(output), "\n") {
164			if trimmed := strings.TrimSpace(line); trimmed != "" {
165				urls = append(urls, trimmed)
166			}
167		}
168		if len(urls) == 0 {
169			return nil, fmt.Errorf("remote %q has no push URL", remoteName)
170		}
171		return urls, nil
172	}
173	
174	// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
175	func ParseURL(rawURL string) (*Info, error) {
176		rawURL = strings.TrimSpace(rawURL)
177	
178		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
179			parts := strings.SplitN(rawURL, ":", 2)
180			if len(parts) != 2 {
181				return nil, fmt.Errorf("invalid SSH URL: %s", RedactURL(rawURL))
182			}
183	
184			hostPart := parts[0]
185			_, host, found := strings.Cut(hostPart, "@")
186			if !found {
187				host = hostPart
188			}
189	
190			pathPart := strings.TrimSuffix(parts[1], ".git")

