  ["integration_capture", "nl -ba cmd/entire/cli/integration_test/checkpoint_sync_remote_test.go | sed -n '300,560p'"],
  ["integration_tail", "nl -ba cmd/entire/cli/integration_test/checkpoint_sync_remote_test.go | sed -n '560,750p'"],
  ["testenv_remote", "nl -ba cmd/entire/cli/integration_test/testenv.go | sed -n '1735,1810p'"],
  ["backend", "nl -ba cmd/entire/cli/integration_test/backend.go | sed -n '1,125p'"],
  ["capture_tests", "rg -n \"TestCaptureCheckpointSyncRemote|pendingCaptureCheckpointSyncRemote|pushurl\" cmd/entire/cli/strategy/*_test.go"]
];
const out = await Promise.all(cmds.map(async ([label, cmd]) => {
  const r = await tools.exec_command({cmd, workdir: "/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-push-remote-eligibility", yield_time_ms: 10000, max_output_tokens: 7000});
  return `## ${label}\n${r.output}`;
}));
text(out.join("\n"));

