216	// configuredRemotesInConfigOrder lists remote names in .git/config section
217	// order (approximates "first remote added"; `git remote` output is
218	// alphabetical and unsuitable). Remotes configured with only pushurl are
219	// deliberately invisible (spec Unit 1). Errors yield an empty list.
220	func configuredRemotesInConfigOrder(ctx context.Context) []string {
221		return cachedRemotesInConfigOrder(ctx, readRemotesInConfigOrder)
222	}
223	
224	// readRemotesInConfigOrder lists remote names, distinguishing "this repo has no
225	// remotes" from "the read failed". Both used to collapse to nil, which was
226	// harmless while every caller re-ran the command — but the per-invocation cache
227	// would memoize a failure's nil as a legitimately empty list and then skip
228	// checkpoint sync for the rest of the process. `git config --get-regexp` exits 1
229	// for no match, so that exit code alone is the empty answer; anything else (a
230	// fork failure under load, a cancelled context, a locked config) is an error the
231	// cache must not keep.
232	func readRemotesInConfigOrder(ctx context.Context) ([]string, error) {
233		cmd := exec.CommandContext(ctx, "git", "config", "--local", "--get-regexp", `^remote\..*\.url$`)
234		if worktreeRoot, ok := settings.WorktreeRoot(ctx); ok {
235			cmd.Dir = worktreeRoot
236		}
237		out, err := cmd.Output()
238		if err != nil {
239			var exitErr *exec.ExitError
240			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
241				return nil, nil // no remote.*.url keys: a real, cacheable answer
242			}
243			return nil, fmt.Errorf("list configured remotes: %w", err)
244		}
245		var names []string
246		seen := map[string]bool{}
